const area = (label, name, value = '') => `<label class="field full">${label}<textarea name="${name}">${esc(value)}</textarea></label>`;
const options = (items, selected) => items.map(x => `<option value="${esc(x)}" ${x === selected ? 'selected' : ''}>${esc(x)}</option>`).join('');
