const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function planner(){
 const items=state.plannerItems||[],today=localDate(new Date()),open=items.filter(i=>i.status==='Offen'),overdue=open.filter(i=>i.date<today),todayItems=open.filter(i=>i.date===today);
 selectedPlannerDate ||= today;
 const year=plannerMonth.getFullYear(),month=plannerMonth.getMonth(),firstDay=(new Date(year,month,1).getDay()+6)%7,days=new Date(year,month+1,0).getDate(),previousDays=new Date(year,month,0).getDate();
 const cells=[];for(let index=0;index<42;index++){const day=index-firstDay+1;let d,current=true;if(day<1){d=new Date(year,month-1,previousDays+day);current=false;}else if(day>days){d=new Date(year,month+1,day-days);current=false;}else d=new Date(year,month,day);const key=localDate(d),dayItems=items.filter(i=>i.date===key);cells.push(`<button class="calendar-day ${current?'':'outside'} ${key===today?'today':''} ${key===selectedPlannerDate?'selected':''}" data-action="select-planner-date" data-date="${key}" aria-label="${d.toLocaleDateString('de-DE')} auswählen, ${dayItems.length} Einträge"><span class="day-top"><span class="day-number">${d.getDate()}</span>${dayItems.length?`<span class="day-count">${dayItems.length}</span>`:''}</span>${dayItems.slice(0,3).map(i=>`<span class="calendar-entry ${i.status==='Erledigt'?'done':''} ${i.priority.toLowerCase()}">${i.time?esc(i.time)+' ':''}${esc(i.title)}</span>`).join('')}${dayItems.length>3?`<span class="sub">+${dayItems.length-3} weitere</span>`:''}</button>`);}
 const upcoming=[...open].sort((a,b)=>`${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`)).slice(0,10);
 const selectedItems=items.filter(i=>i.date===selectedPlannerDate).sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99')),selectedLabel=new Date(`${selectedPlannerDate}T00:00:00`).toLocaleDateString('de-DE',{weekday:'long',day:'2-digit',month:'long',year:'numeric'});
 return head('Kalender & Planer','Aufgaben, Termine und Erinnerungen – privat auf diesem Gerät.',button('＋ Eintrag anlegen','new-planner','','primary'))+
 `<div class="stats"><div class="stat ${overdue.length?'feature':''}"><p class="muted">Überfällig</p><div class="number">${overdue.length}</div><span class="muted">Offene Einträge</span></div><div class="stat"><p class="muted">Heute</p><div class="number">${todayItems.length}</div><span class="muted">Noch zu erledigen</span></div><div class="stat"><p class="muted">Offen gesamt</p><div class="number">${open.length}</div><span class="muted">Aufgaben und Termine</span></div><div class="stat"><p class="muted">Erledigt</p><div class="number">${items.filter(i=>i.status==='Erledigt').length}</div><span class="muted">Gespeicherter Fortschritt</span></div></div>`+
 `<div class="planner-layout"><section class="panel calendar-panel"><div class="panel-head"><div class="actions"><button class="button small" data-action="planner-prev" aria-label="Vorheriger Monat">←</button><h2>${plannerMonth.toLocaleDateString('de-DE',{month:'long',year:'numeric'})}</h2><button class="button small" data-action="planner-next" aria-label="Nächster Monat">→</button></div>${button('Heute','planner-today','','small')}</div><div class="calendar-legend"><span><i class="legend-dot normal"></i>Normal</span><span><i class="legend-dot wichtig"></i>Wichtig</span><span><i class="legend-dot dringend"></i>Dringend</span></div><div class="calendar-weekdays">${['Mo','Di','Mi','Do','Fr','Sa','So'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${cells.join('')}</div></section><aside><section class="panel selected-day"><div class="panel-head"><div><span class="eyebrow">AUSGEWÄHLTER TAG</span><h2>${esc(selectedLabel)}</h2></div>${button('＋ Eintrag','new-planner','', 'small primary').replace('data-id=""',`data-id="" data-date="${selectedPlannerDate}"`)}</div>${selectedItems.length?selectedItems.map(i=>`<div class="planner-item ${i.status==='Erledigt'?'is-done':''}"><button class="planner-check ${i.status==='Erledigt'?'checked':''}" data-action="toggle-planner" data-id="${esc(i.id)}" aria-label="${i.status==='Erledigt'?'Wieder öffnen':'Als erledigt markieren'}">✓</button><button class="planner-main" data-action="edit-planner" data-id="${esc(i.id)}"><strong>${esc(i.title)}</strong><span>${i.time?esc(i.time)+' · ':''}${esc(i.type)}${i.notes?' · '+esc(i.notes):''}</span></button><span class="priority ${i.priority.toLowerCase()}">${esc(i.priority)}</span></div>`).join(''):empty('Dieser Tag ist frei','Klicke auf „Eintrag“, um etwas zu planen.')}</section><section class="panel"><h2>Als Nächstes</h2>${upcoming.length?upcoming.map(i=>`<div class="planner-item"><button class="planner-check" data-action="toggle-planner" data-id="${esc(i.id)}" aria-label="Als erledigt markieren">✓</button><button class="planner-main" data-action="edit-planner" data-id="${esc(i.id)}"><strong>${esc(i.title)}</strong><span>${new Date(`${i.date}T00:00:00`).toLocaleDateString('de-DE',{weekday:'short',day:'2-digit',month:'2-digit'})}${i.time?' · '+esc(i.time):''} · ${esc(i.type)}</span></button><span class="priority ${i.priority.toLowerCase()}">${esc(i.priority)}</span></div>`).join(''):empty('Nichts offen','Lege dein nächstes Ziel oder einen Termin an.')}</section><section class="panel"><h2>Vorschläge für dich</h2>${plannerSuggestions(state,today).map(s=>`<div class="suggestion"><span class="badge">${esc(s.kind)}</span><p>${esc(s.text)}</p></div>`).join('')}</section></aside></div>`;
}
function editPlanner(id,presetDate=''){
 const item=(state.plannerItems||[]).find(i=>i.id===id)||{id:uid(),title:'',date:presetDate||localDate(new Date()),time:'',type:'Aufgabe',priority:'Normal',status:'Offen',notes:''};
 modal(id?'Eintrag bearbeiten':'Neuer Planereintrag',`<div class="form-grid">${field('Titel','title',item.title,'text','',true,true)}${field('Datum','date',item.date,'date','',false,true)}${field('Uhrzeit, optional','time',item.time,'time')}<label class="field">Art<select name="type">${options(['Aufgabe','Termin','Erinnerung'],item.type)}</select></label><label class="field">Priorität<select name="priority">${options(['Normal','Wichtig','Dringend'],item.priority)}</select></label><label class="field">Status<select name="status">${options(['Offen','Erledigt'],item.status)}</select></label>${area('Notizen','notes',item.notes)}</div>${id?button('Eintrag löschen','delete-planner',id,'danger small'):''}`,async f=>{const next=structuredClone(state);next.plannerItems??=[];const row={id:item.id,title:f.get('title').trim(),date:f.get('date'),time:f.get('time'),type:f.get('type'),priority:f.get('priority'),status:f.get('status'),notes:f.get('notes').trim()};const index=next.plannerItems.findIndex(i=>i.id===item.id);if(index<0)next.plannerItems.push(row);else next.plannerItems[index]=row;await persist(next);});
}
function overview() {
 const ready = state.products.filter(p => calculate(p, state.settings).net !== null).length;
 const open = state.quotes.filter(q => ['Entwurf','Angeboten'].includes(q.status)).length;
 const today=localDate(new Date()),due=(state.plannerItems||[]).filter(i=>i.status==='Offen'&&i.date<=today);
 return head('Alles im Blick.', 'Deine Produkte, Preise und Angebote an einem Ort.', button('＋ Produkt anlegen','new-product','','primary')) + `<div class="stats"><div class="stat feature"><p class="muted">Produkte im Sortiment</p><div class="number">${state.products.length}</div><span class="muted">Textilien, Aufkleber & mehr</span></div><div class="stat"><p class="muted">Mit Verkaufspreis</p><div class="number">${ready}<span class="muted"> / ${state.products.length}</span></div><span class="muted">${state.products.length-ready} Preise noch offen</span></div><div class="stat"><p class="muted">Kunden</p><div class="number">${state.customers.length}</div><span class="muted">Gespeicherte Kontakte</span></div><div class="stat"><p class="muted">Offene Angebote</p><div class="number">${open}</div><span class="muted">Entwürfe und angebotene Aufträge</span></div></div>${due.length?`<div class="notice warn"><strong>${due.length} ${due.length===1?'Eintrag ist':'Einträge sind'} heute fällig oder überfällig.</strong> ${button('Kalender öffnen','go-planner','','small')}</div>`:''}${state.settings.taxRate === null ? '<div class="notice warn">Deine Steuereinstellung ist noch offen. In den Einstellungen kannst du den verwendeten Steuersatz festlegen. Bis dahin werden keine Bruttopreise berechnet.</div>' : ''}<div class="two-col"><section class="panel"><div class="panel-head"><h2>Dein Sortiment</h2>${button('Alle Produkte →','go-products','','small')}</div>${productTable(state.products.slice(0,5))}</section><section class="panel"><h2>Schritt für Schritt startklar</h2><div class="step"><span class="step-num">1</span><div><strong>Grundlagen festlegen</strong><p class="muted">Firmendaten, Stundensatz und Steuer in den Einstellungen ergänzen.</p></div></div><div class="step"><span class="step-num">2</span><div><strong>Deine Preise eintragen</strong><p class="muted">Einkauf und Veredelung ergänzen. Leere Felder bedeuten „noch offen“.</p></div></div><div class="step"><span class="step-num">3</span><div><strong>Angebote erstellen</strong><p class="muted">Kunden auswählen, Positionen ergänzen und als PDF drucken.</p></div></div>${button('Einstellungen öffnen','go-settings','','small')}</section></div><section class="panel"><div class="panel-head"><h2>Letzte Angebote</h2>${button('Angebot erstellen','new-quote','','small')}</div>${quoteTable(state.quotes.slice(-4).reverse())}</section>`;
}
function productTable(rows) { if (!rows.length) return empty('Keine Produkte gefunden', 'Lege ein Produkt an oder ändere die Suche.'); return `<div class="table-wrap"><table><thead><tr><th>Produkt</th><th>Kategorie</th><th class="numeric">EK netto</th><th class="numeric">VK netto</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(p => { const c = calculate(p,state.settings); return `<tr><td><strong>${esc(p.name)}</strong><span class="sub">${esc(p.variant || p.sku || p.unit)}</span></td><td>${esc(p.category)}</td><td class="numeric">${money(p.ek)}</td><td class="numeric"><strong>${money(c.net)}</strong></td><td><span class="badge ${c.complete ? 'green' : 'amber'}">${c.complete ? 'Kalkuliert' : 'Kosten offen'}</span>${p.visible ? '<span class="sub">Für Kunden freigegeben</span>' : ''}</td><td>${button('Bearbeiten','edit-product',p.id,'small')}</td></tr>`; }).join('')}</tbody></table></div>`; }
function products() { return head('Produkte & Preise', 'Dein Sortiment mit Einkauf, Kalkulation und Verkauf.', button('＋ Produkt anlegen','new-product','','primary')) + `<section class="panel"><div class="toolbar"><input id="search" aria-label="Produkte suchen" placeholder="Produkt, Artikelnummer oder Variante suchen …" value="${esc(query)}"><select id="category-filter" aria-label="Kategorie filtern"><option value="">Alle Kategorien</option>${options(categories,category)}</select></div><div id="product-results">${filteredProducts()}</div></section><p class="helper">Alle internen Preise sind Nettopreise. Ein leeres Kostenfeld ist ein unbekannter Wert; trage 0 ein, wenn keine Kosten anfallen.</p>`; }
function filteredProducts() { return productTable(state.products.filter(p => (!category || p.category === category) && `${p.name} ${p.sku} ${p.variant}`.toLowerCase().includes(query.toLowerCase()))); }
function modal(title, body, onSubmit) { dialog.className=''; dialog.innerHTML = `<div class="dialog-head"><h2>${title}</h2><button class="close" type="button" data-action="close" aria-label="Schließen">×</button></div><form id="modal-form">${body}<p class="error" id="form-error" role="alert"></p><div class="form-footer"><button type="button" class="button" data-action="close">Abbrechen</button><button type="submit" class="button primary">Speichern</button></div></form>`; dialog.showModal(); $('#modal-form').onsubmit = async e => { e.preventDefault(); const submit = $('button[type=submit]',e.target); submit.disabled = true; try { await onSubmit(new FormData(e.target)); dialog.close(); shell(); toast('Gespeichert.'); } catch(error) { $('#form-error').textContent=error.message; } finally { submit.disabled=false; } }; }
const valueNumber = (f,k) => f.get(k) === '' ? null : Number(f.get(k));
function editProduct(id) { const p = state.products.find(x => x.id === id) || { id:uid(), category:'Textilien', unit:'Stück' }; modal(id ? 'Produkt bearbeiten' : 'Neues Produkt', `<div class="notice"><strong>Private lokale Daten:</strong> EK, Lieferant, Kosten, Arbeitszeit, Ertrag und Marge werden nicht in den öffentlichen VK-Export übernommen.</div><div class="form-grid">${field('Produktname','name',p.name,'text','',false,true)}${field('Artikelnummer','sku',p.sku)}<label class="field">Kategorie<select name="category">${options(categories,p.category)}</select></label>${field('Einheit','unit',p.unit,'text','z. B. Stück, Bogen, m²',false,true)}${field('Variante / Größe / Farbe','variant',p.variant)}${field('Lieferant','supplier',p.supplier)}${area('Beschreibung für Kunden','description',p.description)}<div class="form-section"><h3>Kosten pro Einheit · netto</h3></div>${field('Einkauf / Rohware (€)','ek',p.ek,'number')}${field('Veredelung / Druckmaterial (€)','finishing',p.finishing,'number')}${field('Arbeitszeit (Minuten)','minutes',p.minutes,'number',`Stundensatz: ${money(state.settings.hourlyRate)} · in Einstellungen ändern`)}${field('Verpackung (€)','packaging',p.packaging,'number')}${field('Weitere Kosten (€)','other',p.other,'number')}${field('Aufschlag auf Gesamtkosten (%)','markup',p.markup,'number')}${field('Eigener VK netto (€), optional','vk',p.vk,'number','Überschreibt den errechneten Verkaufspreis.',true)}<label class="checkbox field full"><span><input name="visible" type="checkbox" ${p.visible ? 'checked' : ''}> In der Kundenansicht freigeben</span><small>Nur mit feststehendem VK und Steuereinstellung sichtbar.</small></label>${area('Interne Notizen','notes',p.notes)}</div>${id ? `<div class="actions" style=""><button class="button danger small" type="button" data-action="delete-product" data-id="${esc(id)}">Produkt löschen</button></div>` : ''}`, async f => { const next=structuredClone(state); const row={id:p.id}; for(const k of ['name','sku','category','unit','variant','supplier','description','notes']) row[k]=f.get(k).trim(); for(const k of ['ek','finishing','minutes','packaging','other','markup','vk']) row[k]=valueNumber(f,k); row.visible=f.has('visible'); const i=next.products.findIndex(x=>x.id===p.id); if(i<0)next.products.push(row);else next.products[i]=row; await persist(next); }); }
function calculator() { return head('Dein privater Kalkulator.', 'EK und Kosten lokal eintragen, berechnen und direkt beim Produkt speichern.') + `<div class="notice"><strong>Nur lokal:</strong> EK, Kosten, Ertrag und Marge werden nicht in den öffentlichen VK-Export geschrieben.</div><div class="two-col"><section class="panel"><label class="field">Produkt laden<select id="calc-product"><option value="">Freie Kalkulation</option>${state.products.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} ${esc(p.variant)}</option>`).join('')}</select></label><form id="calc-form" class="form-grid"><div class="form-section"><h3>Kosten & Verkauf</h3></div>${field('Einkauf netto (€)','ek','','number')}${field('Veredelung netto (€)','finishing','','number')}${field('Arbeitszeit (Minuten)','minutes','','number')}${field('Stundensatz (€)','hourlyRate',state.settings.hourlyRate,'number')}${field('Verpackung (€)','packaging','','number')}${field('Weitere Kosten (€)','other','','number')}${field('Aufschlag (%)','markup','','number')}${field('Eigener VK netto (€)','vk','','number')}</form><p class="helper">Aufschlag bezieht sich auf die Gesamtkosten. Die Marge bezieht sich auf den Verkaufspreis. Leere Kosten müssen noch ergänzt werden.</p><div class="actions">${button('EK & Kalkulation im Produkt speichern','save-calculation','','primary')}</div></section><section><div id="calc-result" class="calc-result"></div><p class="helper">Die Kalkulation betrachtet Kosten und Verkauf pro Einheit. Mengenrabatte kannst du im Angebot festlegen.</p></section></div>`; }
function calcData() { const f=new FormData($('#calc-form')); const p={}; for(const k of ['ek','finishing','minutes','packaging','other','markup','vk'])p[k]=valueNumber(f,k);return {p,settings:{...state.settings,hourlyRate:valueNumber(f,'hourlyRate')}}; }
function bindCalculator() { const update=()=>{const {p,settings}=calcData(),c=calculate(p,settings);$('#calc-result').innerHTML=`<p class="muted">VERKAUFSPREIS NETTO</p><div class="big">${money(c.net)}</div><p class="muted">${p.vk!==null?'Eigener Verkaufspreis':'Aus Kosten und Aufschlag berechnet'}</p><div class="calc-line"><span>Gesamtkosten</span><strong>${money(c.cost)}</strong></div><div class="calc-line"><span>Errechneter VK netto</span><strong>${money(c.suggested)}</strong></div><div class="calc-line"><span>Ertrag pro Einheit</span><strong>${money(c.profit)}</strong></div><div class="calc-line"><span>Marge</span><strong>${c.margin===null?'Offen':c.margin.toLocaleString('de-DE')+' %'}</strong></div><div class="calc-line"><span>VK brutto ${settings.taxRate===null?'':`(${settings.taxRate} % USt.)`}</span><strong>${money(c.gross)}</strong></div>${c.profit!==null&&c.profit<0?'<p>Der Verkaufspreis liegt unter deinen Kosten.</p>':''}`;}; $('#calc-form').oninput=update; $('#calc-form').onsubmit=e=>e.preventDefault();$('#calc-product').onchange=e=>{const p=state.products.find(p=>p.id===e.target.value)||{};for(const k of ['ek','finishing','minutes','packaging','other','markup','vk'])$(`[name=${k}]`,$('#calc-form')).value=p[k]??'';update();};update(); }
function customers() { return head('Deine Kunden', 'Kontaktdaten und Notizen für deine Angebote.',button('＋ Kunde anlegen','new-customer','','primary'))+`<section class="panel">${state.customers.length?`<div class="table-wrap"><table><thead><tr><th>Name / Firma</th><th>E-Mail</th><th>Telefon</th><th>Angebote</th><th></th></tr></thead><tbody>${state.customers.map(c=>`<tr><td><strong>${esc(c.name)}</strong><span class="sub">${esc(c.company)}</span></td><td>${esc(c.email)||'—'}</td><td>${esc(c.phone)||'—'}</td><td>${state.quotes.filter(q=>q.customerId===c.id).length}</td><td>${button('Bearbeiten','edit-customer',c.id,'small')}</td></tr>`).join('')}</tbody></table></div>`:empty('Dein erster Kunde fehlt noch.','Lege Kontakte an, um sie in Angeboten wiederzuverwenden.')}</section>`; }
function editCustomer(id) {const c=state.customers.find(x=>x.id===id)||{id:uid()};modal(id?'Kunde bearbeiten':'Neuer Kunde',`<div class="form-grid">${field('Name','name',c.name,'text','',false,true)}${field('Firma','company',c.company)}${field('E-Mail','email',c.email,'email')}${field('Telefon','phone',c.phone,'tel')}${area('Anschrift','address',c.address)}${area('Interne Notizen','notes',c.notes)}</div>${id?button('Kunde löschen','delete-customer',id,'danger small'):''}`,async f=>{const next=structuredClone(state),row={id:c.id};for(const k of ['name','company','email','phone','address','notes'])row[k]=f.get(k).trim();const i=next.customers.findIndex(x=>x.id===c.id);if(i<0)next.customers.push(row);else next.customers[i]=row;await persist(next);}); const del=$('[data-action=delete-customer]',dialog);if(del)del.type='button';}
function quoteTable(rows) {return rows.length?`<div class="table-wrap"><table><thead><tr><th>Angebot</th><th>Kunde</th><th class="numeric">Summe netto</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(q=>`<tr><td><strong>${esc(q.number)}</strong><span class="sub">${esc(q.date)}</span></td><td>${esc(q.customerName)||'Ohne Kunde'}</td><td class="numeric">${money(quoteTotals(q).net)}</td><td><span class="badge ${q.status==='Angenommen'?'green':''}">${esc(q.status)}</span></td><td>${button('Öffnen','view-quote',q.id,'small')}</td></tr>`).join('')}</tbody></table></div>`:empty('Noch keine Angebote','Erstelle dein erstes Angebot aus Produkten oder eigenen Positionen.');}
function quotes(){return head('Angebote','Gespeicherte Preise bleiben im Angebot erhalten.',button('＋ Angebot erstellen','new-quote','','primary'))+`<section class="panel">${quoteTable([...state.quotes].reverse())}</section>`;}
function quoteRow(item={name:'',quantity:1,unit:'Stück',price:''}){return `<div class="quote-item"><input name="item-name" aria-label="Positionsbezeichnung" placeholder="Position" value="${esc(item.name)}" required><input name="item-quantity" aria-label="Menge" type="number" min="0.01" max="10000000" step="0.01" value="${esc(item.quantity)}" required><input name="item-unit" aria-label="Einheit" value="${esc(item.unit)}" required><input name="item-price" aria-label="Einzelpreis netto" type="number" min="0" max="10000000" step="0.01" value="${esc(item.price)}" required><button type="button" class="button" data-action="remove-item" aria-label="Position entfernen">×</button></div>`;}
function orderChoices(taxRate=state.settings.taxRate){
 const products=state.products.filter(p=>calculate(p,state.settings).net!==null).map(p=>({id:`product:${p.id}`,group:'Textilien & Produkte',label:[p.name,p.variant].filter(Boolean).join(' · '),item:{name:[p.name,p.variant].filter(Boolean).join(' · '),quantity:1,unit:p.unit,price:calculate(p,state.settings).net}}));
 const stickers=(listPriceNet(1,state.stickerPriceList?.priceType,taxRate)!==null?state.stickerPriceList.formats:[]).flatMap((format,formatIndex)=>format.variants.flatMap((variant,variantIndex)=>variant.tiers.map((tier,tierIndex)=>({id:`sticker:${formatIndex}:${variantIndex}:${tierIndex}`,group:'Aufkleber-Packs',label:`${format.format} · ${variant.material} · ${tier.quantity} Stück`,item:{name:`Aufkleber-Pack · ${format.format} · ${variant.material} · ${tier.quantity} Stück`,quantity:1,unit:'Pack',price:listPriceNet(tier.total,state.stickerPriceList.priceType,taxRate)}}))));
 return [...products,...stickers];
}
function orderChoiceOptions(taxRate=state.settings.taxRate){const choices=orderChoices(taxRate),groups=[...new Set(choices.map(choice=>choice.group))];return groups.map(group=>`<optgroup label="${esc(group)}">${choices.filter(choice=>choice.group===group).map(choice=>`<option value="${esc(choice.id)}">${esc(choice.label)} · ${money(choice.item.price)}</option>`).join('')}</optgroup>`).join('');}
function bindOrderTax(selectId){const input=$('[name=taxRate]',dialog);if(input)input.addEventListener('change',()=>{$(selectId).innerHTML='<option value="">Position hinzufügen …</option>'+orderChoiceOptions(valueNumber(new FormData($('#modal-form')),'taxRate'));});}
function addOrderChoice(selectId,rowsId){const select=$(selectId),choice=orderChoices(valueNumber(new FormData($('#modal-form')),'taxRate')).find(choice=>choice.id===select.value);if(!choice)return;const rows=$(rowsId);if(rows.children.length===1&&!$('[name=item-name]',rows).value)rows.innerHTML='';rows.insertAdjacentHTML('beforeend',quoteRow(choice.item));select.value='';}
function editQuote(id){const existing=state.quotes.find(q=>q.id===id);let seq=1;while(state.quotes.some(q=>q.number===`HP67-${new Date().getFullYear()}-${String(seq).padStart(3,'0')}`))seq++;const q=existing||{id:uid(),number:`HP67-${new Date().getFullYear()}-${String(seq).padStart(3,'0')}`,date:date(),validUntil:'',status:'Entwurf',customerId:'',note:state.settings.offerNote,discount:0,taxRate:state.settings.taxRate,items:[]};modal(existing?'Angebot bearbeiten':'Neues Angebot',`<div class="form-grid">${field('Angebotsnummer','number',q.number,'text','',false,true)}<label class="field">Kunde<select name="customerId"><option value="">Ohne Kundenkontakt</option>${q.customerId&&!state.customers.some(c=>c.id===q.customerId)?`<option value="${esc(q.customerId)}" selected>${esc(q.customerName)} (gespeicherte Anschrift)</option>`:''}${state.customers.map(c=>`<option value="${esc(c.id)}" ${q.customerId===c.id?'selected':''}>${esc(c.name)} ${esc(c.company)}</option>`).join('')}</select></label>${field('Datum','date',q.date,'date','',false,true)}${field('Gültig bis','validUntil',q.validUntil,'date')}<label class="field">Status<select name="status">${options(['Entwurf','Angeboten','Angenommen','Abgelehnt'],q.status)}</select></label>${field('Rabatt auf alle Positionen (%)','discount',q.discount,'number')}${field('Umsatzsteuer (%)','taxRate',q.taxRate,'number','Leer = noch offen; 0 = keine Umsatzsteuer.')}${area('Hinweis für Kunden','note',q.note)}<div class="form-section"><h3>Positionen · Einzelpreise netto</h3><p class="helper">Aufkleber-Packs sind erst mit bestätigter Verkaufspreisart verfügbar. Bruttopreise werden anhand der Umsatzsteuer dieses Belegs in netto umgerechnet.</p></div><div class="field full"><select id="quote-product" aria-label="Position hinzufügen"><option value="">Produkt oder bestätigten Aufkleber-Preis hinzufügen …</option>${orderChoiceOptions(q.taxRate)}</select><div class="quote-item quote-labels"><span>Bezeichnung</span><span>Menge</span><span>Einheit</span><span>Netto €</span><span></span></div><div id="quote-items">${(q.items.length?q.items:[undefined]).map(quoteRow).join('')}</div><button class="button small" data-action="add-item" type="button">＋ Eigene Position</button><p class="muted" id="quote-live-total"></p></div></div>`,async f=>{const next=structuredClone(state),customer=state.customers.find(c=>c.id===f.get('customerId'));const row={...q,number:f.get('number').trim(),date:f.get('date'),validUntil:f.get('validUntil'),status:f.get('status'),customerId:f.get('customerId'),customerName:customer?[customer.company,customer.name].filter(Boolean).join('\n'):(existing?.customerId===f.get('customerId')?existing.customerName:''),customerAddress:customer?.address||(existing?.customerId===f.get('customerId')?existing.customerAddress:''),note:f.get('note').trim(),discount:valueNumber(f,'discount'),taxRate:valueNumber(f,'taxRate'),sender:existing?.sender||Object.fromEntries(['business','owner','address','email','phone','taxNote'].map(k=>[k,state.settings[k]])),items:[...$('#quote-items').children].map(el=>({name:$('[name=item-name]',el).value.trim(),quantity:Number($('[name=item-quantity]',el).value),unit:$('[name=item-unit]',el).value.trim(),price:Number($('[name=item-price]',el).value)}))};if(row.validUntil&&row.validUntil<row.date)throw Error('Das Gültigkeitsdatum liegt vor dem Angebotsdatum.');const i=next.quotes.findIndex(x=>x.id===q.id);if(i<0)next.quotes.push(row);else next.quotes[i]=row;await persist(next);});bindOrderTax('#quote-product');$('#quote-product').onchange=()=>addOrderChoice('#quote-product','#quote-items');}
