function invoices(){return head('Rechnungen','Zwei Vorlagen: ausführlich für Kunden oder einfach für deine interne Übersicht.',button('＋ Komplette Rechnung','new-full-invoice','','primary')+button('＋ Einfache Rechnung','new-simple-invoice'))+`<div class="notice"><strong>Einfache Rechnung:</strong> persönlicher interner Beleg ohne gesetzliche Prüfung. <strong>Komplette Rechnung:</strong> ausführliche Vorlage mit Kunden-, Leistungs- und Zahlungsdaten.</div><section class="panel">${invoiceTable([...(state.invoices||[])].reverse())}</section>`;}
function editInvoice(type='Komplett',id='',fromQuoteId=''){
 const existing=(state.invoices||[]).find(i=>i.id===id),q=state.quotes.find(q=>q.id===fromQuoteId),due=new Date();due.setDate(due.getDate()+14);
 const invoice=existing||{id:uid(),type,number:invoiceNumber(),issueDate:date(),serviceDate:date(),dueDate:type==='Komplett'?localDate(due):'',status:type==='Komplett'?'Offen':'Entwurf',customerId:q?.customerId||'',customerName:q?.customerName||'',customerAddress:q?.customerAddress||'',note:q?`Übernommen aus Angebot ${q.number}`:'',taxRate:type==='Komplett'?(q?.taxRate??state.settings.taxRate):0,discount:q?.discount||0,items:q?.items?.map(i=>({...i}))||[]};
 const full=invoice.type==='Komplett';
 modal(existing?`${full?'Komplette':'Einfache'} Rechnung bearbeiten`:`Neue ${full?'komplette':'einfache interne'} Rechnung`,`<div class="notice">${full?'Ausführliche Rechnung mit Kundendaten, Leistungsdatum und Zahlungsziel.':'Nur für deine interne Übersicht: Artikel, Menge, Preis und kurze Notiz. Nach dem Speichern kannst du sie direkt als Bild sichern.'}</div><div class="form-grid">${field('Rechnungsnummer','number',invoice.number,'text','',false,true)}${field('Datum','issueDate',invoice.issueDate,'date','',false,true)}${full?`${field('Leistungsdatum','serviceDate',invoice.serviceDate,'date','',false,true)}${field('Zahlbar bis','dueDate',invoice.dueDate,'date')}<label class="field full">Kunde<select name="customerId"><option value="">Kunde auswählen …</option>${invoice.customerId&&!state.customers.some(c=>c.id===invoice.customerId)?`<option value="${esc(invoice.customerId)}" selected>${esc(invoice.customerName)} (gespeicherte Anschrift)</option>`:''}${state.customers.map(c=>`<option value="${esc(c.id)}" ${invoice.customerId===c.id?'selected':''}>${esc(c.name)} ${esc(c.company)}</option>`).join('')}</select></label>${field('Umsatzsteuer (%)','taxRate',invoice.taxRate,'number')}${field('Rabatt (%)','discount',invoice.discount,'number')}<label class="field">Status<select name="status">${options(['Entwurf','Offen','Bezahlt','Storniert'],invoice.status)}</select></label>`:`<input type="hidden" name="serviceDate" value="${esc(invoice.issueDate)}"><input type="hidden" name="taxRate" value="0"><input type="hidden" name="discount" value="0"><input type="hidden" name="status" value="Entwurf">`}${area(full?'Hinweis / Zahlungsinformation':'Kurze Notiz','note',invoice.note)}<div class="form-section"><h3>Positionen</h3><p class="helper">Aufkleber-Packs sind erst mit bestätigter Verkaufspreisart verfügbar.</p></div><div class="field full"><select id="invoice-product" aria-label="Position hinzufügen"><option value="">Textilie, Produkt oder Aufkleber-Pack hinzufügen …</option>${orderChoiceOptions(invoice.taxRate)}</select><div id="invoice-items">${(invoice.items.length?invoice.items:[undefined]).map(quoteRow).join('')}</div><button type="button" class="button small" data-action="add-invoice-item">＋ Eigene Position</button></div></div>${existing?button('Rechnung löschen','delete-invoice',existing.id,'danger small'):''}`,async f=>{const next=structuredClone(state);next.invoices??=[];const customer=state.customers.find(c=>c.id===f.get('customerId'));if(full&&!customer&&!(invoice.customerId===f.get('customerId')&&invoice.customerName))throw Error('Bitte für die komplette Rechnung einen Kunden auswählen.');const row={...invoice,number:f.get('number').trim(),issueDate:f.get('issueDate'),serviceDate:full?f.get('serviceDate'):f.get('issueDate'),dueDate:full?f.get('dueDate'):'',status:full?f.get('status'):'Entwurf',customerId:customer?.id||(full?invoice.customerId:''),customerName:customer?[customer.company,customer.name].filter(Boolean).join('\n'):(full?invoice.customerName:''),customerAddress:customer?customer.address:(full?invoice.customerAddress:''),note:f.get('note').trim(),taxRate:valueNumber(f,'taxRate'),discount:valueNumber(f,'discount'),items:[...$('#invoice-items').children].map(el=>({name:$('[name=item-name]',el).value.trim(),quantity:Number($('[name=item-quantity]',el).value),unit:$('[name=item-unit]',el).value.trim(),price:Number($('[name=item-price]',el).value)})),sender:Object.fromEntries(['business','owner','address','email','phone','taxNumber','vatId','iban','bic','bankName','taxNote'].map(k=>[k,existing?.sender?.[k]||state.settings[k]||'']))};const index=next.invoices.findIndex(i=>i.id===invoice.id);if(index<0)next.invoices.push(row);else next.invoices[index]=row;await persist(next);selectedInvoice=invoice.id;view='invoice';});
 bindOrderTax('#invoice-product');$('#invoice-product').onchange=()=>addOrderChoice('#invoice-product','#invoice-items');
}
function invoiceProblems(i){if(!i)return ['Rechnung nicht gefunden'];if(i.type==='Einfach')return[];const s=i.sender||state.settings,problems=[];if(!s.business||!s.address)problems.push('vollständiger Absender');if(!s.taxNumber&&!s.vatId)problems.push('Steuernummer oder USt-IdNr.');if(!i.customerName||!i.customerAddress)problems.push('vollständige Kundenanschrift');if(i.taxRate===null)problems.push('Steuerangabe');return problems;}
function invoiceView(){const i=(state.invoices||[]).find(i=>i.id===selectedInvoice);if(!i)return empty('Rechnung nicht gefunden','Bitte öffne die Rechnungsübersicht.');const t=invoiceTotals(i),s=i.sender||state.settings,simple=i.type==='Einfach',problems=invoiceProblems(i);return head(esc(i.number),simple?'Einfacher interner Beleg ohne Status.':'Ausführliche Rechnung.',button('← Rechnungen','go-invoices')+button('Bearbeiten','edit-invoice',i.id)+button('Löschen','delete-invoice',i.id,'danger')+(simple?button('Als Bild speichern','invoice-image',i.id,'primary')+button('Drucken / PDF','print-invoice',i.id):button('Drucken / PDF','print-invoice',i.id,'primary')))+`${problems.length?`<div class="notice warn no-print">Vor dem Drucken fehlen: ${esc(problems.join(', '))}. Unter Einstellungen oder Rechnung ergänzen.</div>`:''}<article class="document ${simple?'simple-invoice':''}"><div class="document-header"><div><div class="document-brand">${esc(s.business)}</div>${simple?'':`<p>${esc([s.owner,s.address,s.email,s.phone].filter(Boolean).join('\n'))}</p>`}</div><div><h2>${simple?'EINFACHER INTERNER BELEG':'RECHNUNG'}</h2><p>${esc(i.number)}<br>Datum: ${esc(i.issueDate)}${simple?'':`<br>Leistungsdatum: ${esc(i.serviceDate)}${i.dueDate?`<br>Zahlbar bis: ${esc(i.dueDate)}`:''}`}</p></div></div>${simple?'':`<p>${esc(i.customerName)}\n${esc(i.customerAddress)}</p>`}<div class="table-wrap"><table><thead><tr><th>Artikel / Leistung</th><th class="numeric">Menge</th><th class="numeric">Preis</th><th class="numeric">Gesamt</th></tr></thead><tbody>${i.items.map(row=>`<tr><td>${esc(row.name)}</td><td class="numeric">${row.quantity.toLocaleString('de-DE')} ${esc(row.unit)}</td><td class="numeric">${money(row.price)}</td><td class="numeric">${money(round(row.quantity*row.price))}</td></tr>`).join('')}</tbody></table></div><div class="document-summary">${simple?`<div class="calc-line total"><span>Summe</span><span>${money(t.net)}</span></div>`:`${t.discount?`<div class="calc-line"><span>Zwischensumme netto</span><span>${money(t.subtotal)}</span></div><div class="calc-line"><span>Rabatt (${i.discount} %)</span><span>− ${money(t.discount)}</span></div>`:''}<div class="calc-line"><span>Summe netto</span><span>${money(t.net)}</span></div><div class="calc-line"><span>Umsatzsteuer ${i.taxRate===null?'offen':i.taxRate+' %'}</span><span>${money(t.tax)}</span></div><div class="calc-line total"><span>Gesamtbetrag</span><span>${money(t.gross)}</span></div>`}</div><p>${esc(i.note)}</p>${simple?'':`<p>${esc(s.taxNote)}</p><div class="footer-note">${esc([s.taxNumber?`Steuernummer: ${s.taxNumber}`:'',s.vatId?`USt-IdNr.: ${s.vatId}`:'',s.iban?`IBAN: ${s.iban}`:'',s.bic?`BIC: ${s.bic}`:'',s.bankName].filter(Boolean).join(' · '))}</div>`}</article>`;}
function downloadSimpleInvoiceImage(invoice){
 const width=1200,padding=70,canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');
 if(!ctx)throw Error('Dieser Browser kann kein PNG erstellen.');
 const columns=[500,160,190,210];ctx.font='19px Segoe UI,Arial';
 const rows=invoice.items.map(item=>{
  const cells=[item.name,item.quantity.toLocaleString('de-DE')+' '+item.unit,money(item.price),money(round(item.quantity*item.price))].map((text,i)=>canvasTextLines(ctx,text,columns[i]-32));
  return {cells,height:Math.max(68,Math.max(...cells.map(lines=>lines.length))*26+26)};
 });
 ctx.font='bold 36px Segoe UI,Arial';const business=canvasTextLines(ctx,invoice.sender?.business||state.settings.business||'HooDPlaka67',width-padding*2);
 ctx.font='20px Segoe UI,Arial';const number=canvasTextLines(ctx,invoice.number,width-padding*2);
 ctx.font='17px Segoe UI,Arial';const note=canvasTextLines(ctx,invoice.note,width-padding*2);
 const header=160+business.length*44+number.length*28,height=Math.max(760,header+48+rows.reduce((sum,row)=>sum+row.height,0)+180+note.length*25+70);
 if(width*height>16000000)throw Error('Der Beleg ist für ein einzelnes PNG zu groß. Bitte Drucken / PDF verwenden.');
 canvas.width=width;canvas.height=height;ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.fillStyle='#17242b';ctx.fillRect(0,0,width,18);ctx.font='bold 36px Segoe UI,Arial';let y=75;
 for(const line of business){ctx.fillText(line,padding,y);y+=44;}ctx.font='bold 25px Segoe UI,Arial';ctx.fillText('EINFACHER INTERNER BELEG',padding,y+10);y+=47;ctx.font='20px Segoe UI,Arial';
 for(const line of number){ctx.fillText(line,padding,y);y+=28;}ctx.fillText(new Date(invoice.issueDate+'T00:00:00').toLocaleDateString('de-DE'),padding,y);y=header;
 ctx.fillStyle='#eef2f3';ctx.fillRect(padding,y,width-padding*2,48);ctx.fillStyle='#52636c';ctx.font='bold 16px Segoe UI,Arial';let x=padding;
 ['ARTIKEL / LEISTUNG','MENGE','PREIS','GESAMT'].forEach((text,i)=>{ctx.textAlign=i?'right':'left';ctx.fillText(text,i?x+columns[i]-16:x+16,y+31);x+=columns[i];});y+=48;
 for(const row of rows){let x=padding;row.cells.forEach((lines,i)=>{ctx.textAlign=i?'right':'left';ctx.fillStyle='#17242b';ctx.font=i===3?'bold 19px Segoe UI,Arial':'19px Segoe UI,Arial';const tx=i?x+columns[i]-16:x+16;lines.forEach((line,j)=>ctx.fillText(line,tx,y+36+j*26));x+=columns[i];});y+=row.height;ctx.strokeStyle='#dde4e7';ctx.beginPath();ctx.moveTo(padding,y);ctx.lineTo(width-padding,y);ctx.stroke();}
 y+=35;ctx.fillStyle='#17242b';ctx.fillRect(padding,y,width-padding*2,76);ctx.fillStyle='#fff';ctx.font='bold 21px Segoe UI,Arial';ctx.textAlign='left';ctx.fillText('SUMME',padding+28,y+47);ctx.textAlign='right';ctx.fillStyle='#d5f768';ctx.font='bold 30px Segoe UI,Arial';ctx.fillText(money(invoiceTotals(invoice).net),width-padding-28,y+50);y+=120;
 ctx.fillStyle='#60717a';ctx.font='17px Segoe UI,Arial';ctx.textAlign='left';for(const line of note){ctx.fillText(line,padding,y);y+=25;}

 canvas.toBlob(blob=>{if(!blob){toast('Bild konnte nicht erstellt werden. Bitte Drucken / PDF verwenden.');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=invoice.number.replace(/[^a-z0-9_-]/gi,'-')+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Interne Rechnung als Bild gespeichert.');},'image/png');
}
function catalog(){const rows=state.products.filter(p=>p.visible&&calculate(p,state.settings).gross!==null);return head(esc(state.settings.business),'Textilien · Aufkleber · Veredelung',button('← Verwaltung','go-overview')+button('Preisliste drucken / PDF','print','','primary'))+`<div class="product-grid">${rows.map(p=>{const c=calculate(p,state.settings);return `<article class="product-card"><span class="badge">${esc(p.category)}</span><h2>${esc(p.name)}</h2><p class="muted">${esc(p.variant)}</p><p>${esc(p.description)}</p><div class="price">${money(c.gross)}</div><p class="muted">pro ${esc(p.unit)} · ${state.settings.taxRate===0?'ohne Umsatzsteuer':`inkl. ${state.settings.taxRate} % USt.`}</p></article>`;}).join('')}</div>${!rows.length?`<section class="panel">${empty('Noch keine Preise veröffentlicht.','Das Sortiment wird gerade vorbereitet.')}</section>`:''}<p class="helper">${esc(state.settings.taxNote)}</p><p class="footer-note">${esc([state.settings.email,state.settings.phone].filter(Boolean).join(' · '))}</p>`;}
function settings(){const s=state.settings;return head('Deine Einstellungen','Grundlagen für deine Kalkulationen und Kundenausgaben.')+`<div class="two-col"><section class="panel"><h2>Firma, Rechnungen & Kalkulation</h2><form id="settings-form"><div class="form-grid">${field('Firmenname','business',s.business,'text','',false,true)}${field('Ansprechpartner','owner',s.owner)}${area('Anschrift','address',s.address)}${field('E-Mail','email',s.email,'email')}${field('Telefon','phone',s.phone,'tel')}<div class="form-section"><h3>Angaben für komplette Rechnungen</h3></div>${field('Steuernummer','taxNumber',s.taxNumber)}${field('USt-IdNr., optional','vatId',s.vatId)}${field('IBAN','iban',s.iban)}${field('BIC','bic',s.bic)}${field('Bankname','bankName',s.bankName)}<div class="form-section"><h3>Kalkulation</h3></div>${field('Stundensatz netto (€)','hourlyRate',s.hourlyRate,'number','Wird für die Arbeitskosten aller Produkte verwendet.')}${field('Umsatzsteuer (%)','taxRate',s.taxRate,'number','Deinen tatsächlich verwendeten Satz eintragen; 0 für ohne Umsatzsteuer.')}${state.stickerPriceList?`<label class="field full">Preisart der Aufkleberliste<select name="stickerPriceType">${Object.entries(priceTypes).filter(([key])=>key!=='vk-tax-unconfirmed').map(([key,label])=>`<option value="${key}" ${state.stickerPriceList.priceType===key?'selected':''}>${esc(label)}</option>`).join('')}</select><small>Nur ändern, wenn die Preisbasis geklärt ist. Die Originalbeträge bleiben unverändert.</small></label>`:''}${area('Steuerhinweis für Kundenausgaben','taxNote',s.taxNote)}${area('Standardtext für neue Angebote','offerNote',s.offerNote)}</div><p class="helper">Gespeicherte Angebote und Rechnungen behalten ihre bisherigen Preise und Absenderdaten.</p><p id="settings-error" class="error" role="alert"></p><div class="form-footer"><button class="button primary">Einstellungen speichern</button></div></form></section><section><div class="panel"><h2>Private Datensicherung</h2><p class="muted">Enthält alle lokalen Daten: EK, Kosten, Margen, Lieferanten, Kunden, Angebote, Rechnungen, Kalender und VK. Diese Datei privat aufbewahren.</p><p class="helper">Damit kannst du deinen vollständigen Datenstand auf ein anderes Gerät übertragen. Vor jedem Import wird der bisherige Stand automatisch gesichert.</p><div class="actions">${button('Private Sicherung exportieren','private-export','','primary')}${button('Private Sicherung importieren','import')}${browserMode&&localStorage.getItem(browserBackupKey)?button('Stand vor letztem Import herunterladen','previous-backup'):''}</div><input id="import-file" type="file" accept=".json,application/json" class="hidden"></div><div class="panel"><h2>Öffentlicher VK-Export</h2><p class="muted">Enthält ausschließlich freigegebene Produktdaten und VK-Preislisten. EK, Kosten, Margen, Lieferanten, Kunden, Angebote, Rechnungen, Kalender und Kontaktdaten fehlen vollständig.</p><div class="actions">${button('Öffentliche VK-Preise exportieren','public-export')}</div></div></section></div>`;}
function bindSettings(){$('#settings-form').onsubmit=async e=>{e.preventDefault();const b=$('button',e.target);b.disabled=true;try{const f=new FormData(e.target),next=structuredClone(state);for(const k of ['business','owner','address','email','phone','taxNumber','vatId','iban','bic','bankName','offerNote','taxNote'])next.settings[k]=f.get(k).trim();for(const k of ['hourlyRate','taxRate'])next.settings[k]=valueNumber(f,k);if(next.stickerPriceList)next.stickerPriceList.priceType=f.get('stickerPriceType');await persist(next);toast('Einstellungen gespeichert.');}catch(err){$('#settings-error').textContent=err.message;}finally{b.disabled=false;}};$('#import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>8e6)throw Error('Die Sicherung ist zu groß (max. 8 MB).');const next=validateState(JSON.parse(await file.text()));if(!confirm(`Diese Sicherung enthält ${next.products.length} Produkte, ${next.customers.length} Kunden, ${next.quotes.length} Angebote und ${(next.invoices||[]).length} Rechnungen. Aktuelle Daten ersetzen? Die bisherigen Daten werden automatisch gesichert.`))return;next.revision=state.revision;await persist(next,{backup:true});shell();toast('Sicherung wiederhergestellt.');}catch(error){toast(error.message);}e.target.value='';};}
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#product-results').innerHTML=filteredProducts();}});
document.addEventListener('change',e=>{if(e.target.id==='category-filter'){category=e.target.value;$('#product-results').innerHTML=filteredProducts();}});
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){view=nav.dataset.nav;shell();return;}const target=e.target.closest('[data-action]');if(!target)return;const {action,id,date:presetDate}=target.dataset;try{
 if(action.startsWith('go-')){view=action.slice(3);shell();}
 else if(action==='new-product'||action==='edit-product')editProduct(id);
 else if(action==='new-customer'||action==='edit-customer')editCustomer(id);
 else if(action==='new-quote'||action==='edit-quote')editQuote(id);
 else if(action==='new-full-invoice')editInvoice('Komplett');
 else if(action==='new-simple-invoice')editInvoice('Einfach');
 else if(action==='edit-invoice'){const current=(state.invoices||[]).find(i=>i.id===id);if(!current)throw Error('Rechnung nicht gefunden.');editInvoice(current.type,id);}
 else if(action==='invoice-from-quote')editInvoice('Komplett','',id);
 else if(action==='new-planner'||action==='edit-planner')editPlanner(id,presetDate);
 else if(action==='select-planner-date'){selectedPlannerDate=presetDate;const selected=new Date(`${presetDate}T00:00:00`);if(selected.getMonth()!==plannerMonth.getMonth()||selected.getFullYear()!==plannerMonth.getFullYear())plannerMonth=new Date(selected.getFullYear(),selected.getMonth(),1);renderContent();}
 else if(action==='planner-prev'||action==='planner-next'){plannerMonth=new Date(plannerMonth.getFullYear(),plannerMonth.getMonth()+(action==='planner-next'?1:-1),1);renderContent();}
 else if(action==='planner-today'){const now=new Date();selectedPlannerDate=localDate(now);plannerMonth=new Date(now.getFullYear(),now.getMonth(),1);renderContent();}
 else if(action==='toggle-planner'){const next=structuredClone(state),item=(next.plannerItems||[]).find(i=>i.id===id);if(!item)throw Error('Eintrag nicht gefunden.');item.status=item.status==='Erledigt'?'Offen':'Erledigt';await persist(next);renderContent();toast(item.status==='Erledigt'?'Erledigt – gut gemacht.':'Eintrag wieder geöffnet.');}
 else if(action==='close'){dialog.close();dialog.className='';}
 else if(action==='view-quote'){selectedQuote=id;view='quote';shell();}
 else if(action==='view-invoice'){selectedInvoice=id;view='invoice';shell();}
 else if(action==='print'){if(view==='quote'&&state.quotes.find(q=>q.id===selectedQuote)?.taxRate===null)throw Error('Bitte zuerst die Umsatzsteuer im Angebot ergänzen.');openPrintView(view==='quote'?'Angebot':view==='stickers'?'Aufkleber-Preisliste':view==='textiles'?'Textilien-Preisliste':'HooDPlaka67 Preisliste');}
 else if(action==='print-invoice'){const invoice=(state.invoices||[]).find(i=>i.id===id);const problems=invoiceProblems(invoice);if(problems.length)throw Error(`Vor dem Drucken fehlen: ${problems.join(', ')}.`);openPrintView(`Rechnung ${invoice.number}`);}
 else if(action==='confirm-print'){document.body.classList.add('printing');window.addEventListener('afterprint',()=>document.body.classList.remove('printing'),{once:true});window.print();}
 else if(action==='download-print')downloadPrintFile();
 else if(action==='price-list-image')downloadPriceListImage(id);
 else if(action==='invoice-image'){const invoice=(state.invoices||[]).find(i=>i.id===id);if(!invoice||invoice.type!=='Einfach')throw Error('Einfache interne Rechnung nicht gefunden.');downloadSimpleInvoiceImage(invoice);}
 else if(action==='add-item')$('#quote-items').insertAdjacentHTML('beforeend',quoteRow());
 else if(action==='add-invoice-item')$('#invoice-items').insertAdjacentHTML('beforeend',quoteRow());
 else if(action==='remove-item')target.closest('.quote-item').remove();
 else if(action==='import')$('#import-file').click();
 else if(action==='private-export'){if(browserMode)downloadJson(state,`HP67-PRIVATE-Sicherung-${date()}.json`);else{const response=await fetch('/api/backup',{headers:{'X-HP67-Token':token}});if(!response.ok)throw Error((await response.json()).error);downloadJson(await response.json(),`HP67-PRIVATE-Sicherung-${date()}.json`);}toast('Private Sicherung exportiert.');}
 else if(action==='previous-backup'){const saved=localStorage.getItem(browserBackupKey);if(!saved)throw Error('Noch keine Sicherung vor einem Import vorhanden.');downloadJson(JSON.parse(saved),`HP67-VOR-IMPORT-${date()}.json`);}
 else if(action==='public-export'){downloadJson(publicCatalog(state),`HP67-OEFFENTLICHE-VK-PREISE-${date()}.json`);toast('Öffentliche VK-Preise exportiert.');}
 else if(action==='delete-product'||action==='delete-customer'){if(!confirm('Diesen Eintrag löschen? Bereits gespeicherte Angebote bleiben erhalten.'))return;const next=structuredClone(state),key=action==='delete-product'?'products':'customers';next[key]=next[key].filter(x=>x.id!==id);await persist(next);dialog.close();shell();toast('Eintrag gelöscht.');}
 else if(action==='delete-planner'){if(!confirm('Diesen Planereintrag löschen?'))return;const next=structuredClone(state);next.plannerItems=(next.plannerItems||[]).filter(i=>i.id!==id);await persist(next);dialog.close();renderContent();toast('Planereintrag gelöscht.');}
 else if(action==='delete-invoice'){const invoice=(state.invoices||[]).find(i=>i.id===id);if(!invoice)throw Error('Rechnung nicht gefunden.');if(!confirm(`Rechnung „${invoice.number}“ löschen?`))return;const next=structuredClone(state);next.invoices=(next.invoices||[]).filter(i=>i.id!==id);await persist(next);dialog.close();selectedInvoice=null;view='invoices';shell();toast('Rechnung gelöscht.');}
 else if(action==='save-calculation'){const id=$('#calc-product').value;if(!id)throw Error('Bitte zuerst ein Produkt auswählen, in das die Kalkulation gespeichert werden soll.');if(!$('#calc-form').reportValidity())return;const {p,settings}=calcData();if(settings.hourlyRate!==state.settings.hourlyRate)throw Error('Der Stundensatz ist hier nur für die Vorschau geändert. Bitte zuerst unter Einstellungen speichern.');const next=structuredClone(state);Object.assign(next.products.find(x=>x.id===id),p);await persist(next);toast('Kalkulation im Produkt gespeichert.');}
 }catch(error){toast(error.message);}});
try{if(browserMode){const saved=localStorage.getItem(browserStorageKey);state=validateState(saved?JSON.parse(saved):await fetch('./initial-state.json').then(response=>response.json()));if(!saved)localStorage.setItem(browserStorageKey,JSON.stringify(state));token='browser-local';}else{const response=await fetch('/api/state');if(!response.ok)throw Error('Verbindung fehlgeschlagen.');({state,token}=await response.json());}shell();}catch(error){$('#app').innerHTML=`<div class="loading"><h1>Das Programm ist nicht erreichbar.</h1><p>${browserMode?'Bitte den lokalen Browspeicher dieser Seite freigeben und neu laden.':'Starte „HooDPlaka67 starten.cmd“ im Programmordner und lade diese Seite erneut.'}</p><p>${esc(error.message)}</p></div>`;}
if (document.modelContext?.registerTool && state) {
 const lifecycle = new AbortController();
 window.addEventListener('pagehide', () => lifecycle.abort(), {once:true});
 try {
  Promise.resolve(document.modelContext.registerTool({
   name:'read_product_prices', title:'Produktpreise lesen',
   description:'Liest aktuelle Produktpreise. In der Kundenansicht ausschließlich freigegebene Bruttopreise; in der Verwaltung auch die interne Kalkulation. Ändert keine Daten.',
   inputSchema:{type:'object',properties:{productIds:{type:'array',items:{type:'string'},maxItems:100}},required:['productIds'],additionalProperties:false},
   annotations:{readOnlyHint:true,untrustedContentHint:true},
   execute(input) {
    if(!input || !Array.isArray(input.productIds) || input.productIds.length>100 || input.productIds.some(id=>typeof id!=='string')) throw Error('productIds muss eine Liste mit höchstens 100 IDs sein.');
    return input.productIds.map(id=>{
     const p=state.products.find(row=>row.id===id);
     if(!p)throw Error('Produkt nicht gefunden.');
     const c=calculate(p,state.settings);
     if(view==='catalog') {if(!p.visible||c.gross===null)throw Error('Produkt nicht freigegeben.');return {id:p.id,name:p.name,unit:p.unit,gross:c.gross};}
     return {id:p.id,name:p.name,unit:p.unit,...c};
    });
   }
  },{signal:lifecycle.signal})).catch(()=>{});
 } catch { /* Optional browser capability; ordinary controls remain available. */ }
}
